function renderSignupUI() {
    return `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sign Up - Zuup</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <script>
        tailwind.config = {
            theme: {
                extend: {
                    colors: {
                        background: '#16171D',
                        card: '#1C1E26',
                        input: '#222530',
                        border: '#2A2D3A',
                        primary: '#FF2E93',
                        muted: '#8A8D9B'
                    },
                    animation: { 'spin': 'spin 1s linear infinite' }
                }
            }
        }
    </script>
    <style>
        body { font-family: 'Inter', sans-serif; background-color: #16171D; color: white; }
        [x-cloak] { display: none !important; }
        input::-webkit-outer-spin-button, input::-webkit-inner-spin-button { -webkit-appearance: none; margin: 0; }
        input[type=number] { -moz-appearance: textfield; }
    </style>
    <script defer src="https://cdn.jsdelivr.net/npm/alpinejs@3.x.x/dist/cdn.min.js"></script>
    <script src="https://challenges.cloudflare.com/turnstile/v0/api.js" defer></script>
</head>
<body class="min-h-screen flex flex-col items-center justify-center p-4 relative overflow-hidden">
    <img src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=" class="absolute -bottom-20 -right-20 w-96 opacity-10 pointer-events-none" />

    <div class="w-full max-w-md bg-card border border-border rounded-2xl p-8 relative z-10 shadow-2xl" x-data="signupForm()">
        <div class="flex justify-center mb-6">
            <svg xmlns="http://www.w3.org/2000/svg" width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#FF2E93" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><line x1="19" y1="8" x2="19" y2="14"/><line x1="22" y1="11" x2="16" y2="11"/></svg>
        </div>

        <h2 class="text-2xl font-bold text-center mb-2" x-text="stepTitles[currentStep]"></h2>
        <p class="text-muted text-center text-sm mb-6" x-text="stepDescriptions[currentStep]"></p>

        <div x-show="errorMessage" x-cloak class="mb-6 p-3 bg-red-500/10 border border-red-500/20 text-red-400 rounded-xl text-sm text-center" x-text="errorMessage"></div>
        <div x-show="successMessage" x-cloak class="mb-6 p-3 bg-green-500/10 border border-green-500/20 text-green-400 rounded-xl text-sm text-center" x-text="successMessage"></div>

        <form @submit.prevent="nextStep">
            <!-- Step 1: Personal Info -->
            <div x-show="currentStep === 1" x-cloak class="space-y-4">
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Full Name</label>
                    <input type="text" x-model="form.name" :required="currentStep === 1" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Date of Birth</label>
                    <input type="date" x-model="form.dob" :required="currentStep === 1" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all [&::-webkit-calendar-picker-indicator]:invert">
                </div>
            </div>

            <!-- Step 2: Contact Info -->
            <div x-show="currentStep === 2" x-cloak class="space-y-4">
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Email Address</label>
                    <input type="email" x-model="form.email" :required="currentStep === 2" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Mobile Number</label>
                    <input type="tel" x-model="form.mobile" :required="currentStep === 2" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
            </div>

            <!-- Step 3: Optional Info -->
            <div x-show="currentStep === 3" x-cloak class="space-y-4">
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Address (Optional)</label>
                    <input type="text" x-model="form.address" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">School / Organization (Optional)</label>
                    <input type="text" x-model="form.school" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
            </div>

            <!-- Step 4: Identity -->
            <div x-show="currentStep === 4" x-cloak class="space-y-4">
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Username</label>
                    <div class="relative">
                        <span class="absolute left-4 top-1/2 -translate-y-1/2 text-muted">@</span>
                        <input type="text" x-model="form.username" @input.debounce.500ms="checkUsername" :required="currentStep === 4" class="w-full pl-9 pr-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                    </div>
                    <p class="text-xs mt-1" :class="usernameStatus.available ? 'text-green-400' : 'text-red-400'" x-show="usernameStatus.message" x-text="usernameStatus.message"></p>
                </div>
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Profile Picture (Optional)</label>
                    <div class="text-xs text-muted mb-2">Note: Mandatory for offline Zuup events.</div>
                    <input type="file" accept="image/*" @change="handleFileUpload" class="w-full px-4 py-2.5 bg-input border border-border rounded-xl text-white text-sm focus:outline-none focus:border-primary transition-all file:mr-4 file:py-1 file:px-3 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-primary file:text-white hover:file:bg-primary/80">
                </div>
            </div>

            <!-- Step 5: Security -->
            <div x-show="currentStep === 5" x-cloak class="space-y-4">
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Password</label>
                    <input type="password" x-model="form.password" :required="currentStep === 5" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>
                <div>
                    <label class="block text-sm font-medium text-muted mb-1.5">Confirm Password</label>
                    <input type="password" x-model="form.confirmPassword" :required="currentStep === 5" class="w-full px-4 py-3 bg-input border border-border rounded-xl text-white placeholder-muted focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                </div>

                <div class="cf-turnstile mt-2 flex justify-center" data-sitekey="0x4AAAAAADpuIfvXpUHXndxC" data-theme="dark"></div>
            </div>

            <!-- Step 6: OTP Verification -->
            <div x-show="currentStep === 6" x-cloak class="space-y-4">
                <div class="flex justify-between gap-2 max-w-[280px] mx-auto mb-6">
                    <template x-for="(d, i) in 6" :key="i">
                        <input type="text" maxlength="1" x-model="otp[i]" :id="'signup-otp-' + i"
                            @input="handleOtpInput(i, $event)" @keydown="handleOtpKeydown(i, $event)"
                            class="w-10 h-12 bg-input border border-border rounded-xl text-center text-xl font-bold text-white focus:outline-none focus:border-primary focus:ring-1 focus:ring-primary transition-all">
                    </template>
                </div>

                <div class="text-center mt-4">
                    <button type="button" @click="resendOtp" :disabled="resendCooldown > 0" class="text-primary text-sm hover:underline disabled:opacity-50 disabled:no-underline">
                        <span x-show="resendCooldown === 0">Resend Code</span>
                        <span x-show="resendCooldown > 0" x-text="\`Resend Code in \${resendCooldown}s\`"></span>
                    </button>
                </div>
            </div>

            <!-- Navigation Buttons -->
            <div class="flex gap-3 mt-8">
                <button type="button" x-show="currentStep > 1 && currentStep < 6" @click="currentStep--" class="w-1/3 px-4 py-3 bg-transparent text-white border border-border hover:bg-input rounded-xl text-[15px] font-semibold transition-all">
                    Back
                </button>
                <button type="submit" :disabled="loading || (currentStep === 4 && !usernameStatus.available && form.username.length > 0)" class="flex-1 px-4 py-3 bg-primary hover:bg-[#E01E79] disabled:opacity-50 text-white rounded-xl text-[15px] font-semibold transition-all shadow-[0_0_15px_rgba(255,46,147,0.3)] hover:shadow-[0_0_20px_rgba(255,46,147,0.5)] flex items-center justify-center gap-2">
                    <span x-show="loading" class="animate-spin w-4 h-4 border-2 border-white/30 border-t-white rounded-full"></span>
                    <span x-show="!loading" x-text="currentStep === 5 ? 'Create Account' : (currentStep === 6 ? 'Verify Email' : 'Continue')"></span>
                </button>
            </div>
        </form>

        <div class="mt-8 text-center" x-show="currentStep === 1">
            <p class="text-muted text-[15px]">Already have an account? <a href="/login" class="text-primary hover:underline">Log in</a></p>
        </div>
    </div>

    <script>
        document.addEventListener('alpine:init', () => {
            Alpine.data('signupForm', () => ({
                currentStep: 1,
                loading: false,
                errorMessage: '',
                successMessage: '',
                stepTitles: { 1: 'Personal Details', 2: 'Contact Info', 3: 'Additional Details', 4: 'Your Identity', 5: 'Security', 6: 'Verify Email' },
                stepDescriptions: { 1: 'Let\\'s get to know you.', 2: 'How we can reach you.', 3: 'Optional information for your profile.', 4: 'Pick your unique username.', 5: 'Secure your account.', 6: 'We sent a 6-digit code to your email.' },

                form: { name: '', dob: '', email: '', mobile: '', address: '', school: '', username: '', avatar: '', password: '', confirmPassword: '' },

                usernameStatus: { message: '', available: false },

                otp: ['', '', '', '', '', ''],
                resendCooldown: 0,
                resendTimer: null,

                get otpCode() { return this.otp.join(''); },

                async checkUsername() {
                    if (this.form.username.length < 3) {
                        this.usernameStatus = { message: 'Must be at least 3 characters', available: false };
                        return;
                    }
                    if (!/^[a-zA-Z0-9_]+$/.test(this.form.username)) {
                        this.usernameStatus = { message: 'Letters, numbers, underscores only', available: false };
                        return;
                    }
                    try {
                        const res = await fetch('/api/signup/check-username', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ username: this.form.username }) });
                        const data = await res.json();
                        this.usernameStatus = { message: data.available ? 'Username available!' : 'Username taken', available: data.available };
                    } catch (e) {
                        this.usernameStatus = { message: 'Error checking username', available: false };
                    }
                },

                handleFileUpload(e) {
                    const file = e.target.files[0];
                    if (!file) return;
                    if (file.size > 2 * 1024 * 1024) { this.errorMessage = 'Image must be less than 2MB'; e.target.value = ''; return; }
                    const reader = new FileReader();
                    reader.onloadend = () => { this.form.avatar = reader.result; };
                    reader.readAsDataURL(file);
                },

                async nextStep() {
                    this.errorMessage = '';
                    if (this.currentStep === 4 && !this.usernameStatus.available) {
                        this.errorMessage = 'Please choose an available username';
                        return;
                    }
                    if (this.currentStep === 5) {
                        if (this.form.password !== this.form.confirmPassword) {
                            this.errorMessage = 'Passwords do not match';
                            return;
                        }
                        if (this.form.password.length < 8) {
                            this.errorMessage = 'Password must be at least 8 characters';
                            return;
                        }
                        await this.submitSignup();
                        return;
                    }
                    if (this.currentStep === 6) {
                        await this.verifyEmail();
                        return;
                    }
                    this.currentStep++;
                },

                async submitSignup() {
                    this.loading = true; this.errorMessage = '';
                    const turnstileToken = document.querySelector('[name="cf-turnstile-response"]')?.value;
                    if (!turnstileToken) {
                        this.errorMessage = 'Please complete the security check';
                        this.loading = false;
                        return;
                    }

                    try {
                        const payload = { ...this.form, turnstileToken };
                        delete payload.confirmPassword;
                        const res = await fetch('/api/signup', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
                        const data = await res.json();
                        if (!res.ok) throw new Error(data.error || 'Failed to create account');

                        this.currentStep = 6;
                        this.startResendCooldown();
                        setTimeout(() => document.getElementById('signup-otp-0')?.focus(), 200);
                    } catch (err) {
                        this.errorMessage = err.message;
                        if (window.turnstile) turnstile.reset();
                    } finally {
                        this.loading = false;
                    }
                },

                async verifyEmail() {
                    if (this.otpCode.length !== 6) { this.errorMessage = 'Enter the full 6-digit code'; return; }
                    this.loading = true; this.errorMessage = '';
                    try {
                        const res = await fetch('/api/signup/verify-email', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: this.form.email, token: this.otpCode }) });
                        const data = await res.json();
                        if (!res.ok) throw new Error(data.error || 'Invalid code');
                        this.successMessage = 'Account verified! Redirecting to login...';
                        setTimeout(() => { window.location.href = '/login'; }, 2000);
                    } catch (err) {
                        this.errorMessage = err.message;
                    } finally {
                        this.loading = false;
                    }
                },

                handleOtpInput(index, event) {
                    const value = event.target.value;
                    if (!/^[0-9]$/.test(value)) { this.otp[index] = ''; return; }
                    if (index < 5 && value) {
                        setTimeout(() => document.getElementById('signup-otp-' + (index + 1))?.focus(), 10);
                    }
                },
                handleOtpKeydown(index, event) {
                    if (event.key === 'Backspace' && !this.otp[index] && index > 0) {
                        document.getElementById('signup-otp-' + (index - 1))?.focus();
                    }
                },

                async resendOtp() {
                    if (this.resendCooldown > 0) return;
                    try {
                        await fetch('/api/otp/send', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: this.form.email, turnstileToken: 'signup_resend' }) });
                        this.successMessage = 'Verification code resent!';
                        setTimeout(() => this.successMessage = '', 3000);
                        this.startResendCooldown();
                    } catch (e) {
                        this.errorMessage = 'Failed to resend code';
                    }
                },
                startResendCooldown() {
                    this.resendCooldown = 60;
                    this.resendTimer = setInterval(() => {
                        this.resendCooldown--;
                        if (this.resendCooldown <= 0) clearInterval(this.resendTimer);
                    }, 1000);
                }
            }));
        });
    </script>
</body>
</html>`;
}

