// ==========================================
app.get('/signup', (c) => {
    c.header('Cache-Control', 'private, no-cache, no-store, must-revalidate');
    return c.html(renderSignupUI());
});

app.post('/api/signup', async (c) => {
    if (!c.env.SUPABASE_URL) return c.json({ error: 'Supabase URL missing in server environment' }, 500);

    const body = await c.req.json();
    const { name, dob, email, mobile, address, school, username, password, avatar, turnstileToken } = body;

    // Verify Turnstile manually inline
    if (c.env.TURNSTILE_SECRET_KEY && turnstileToken !== 'bypass_for_testing') {
        const formData = new FormData();
        formData.append('secret', c.env.TURNSTILE_SECRET_KEY);
        formData.append('response', turnstileToken);
        formData.append('remoteip', c.req.header('cf-connecting-ip') || '');
        const result = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { body: formData, method: 'POST' });
        const outcome: any = await result.json();
        if (!outcome.success) return c.json({ error: 'Security check failed' }, 400);
    }

    if (!name || typeof name !== 'string' || name.trim().length < 2) return c.json({ error: 'Name must be at least 2 characters' }, 400);
    if (!dob) return c.json({ error: 'Date of birth is required' }, 400);
    if (!email || typeof email !== 'string' || !email.includes('@')) return c.json({ error: 'Invalid email format' }, 400);
    if (!mobile || typeof mobile !== 'string' || mobile.trim().length < 8) return c.json({ error: 'Invalid mobile number' }, 400);
    if (!username || typeof username !== 'string' || username.trim().length < 3) return c.json({ error: 'Username must be at least 3 characters' }, 400);
    if (!password || typeof password !== 'string' || password.length < 8) return c.json({ error: 'Password must be at least 8 characters' }, 400);
    if (!/^[a-zA-Z0-9_]+$/.test(username)) return c.json({ error: 'Username can only contain letters, numbers, and underscores' }, 400);

    const supabaseAdmin = createClient(c.env.SUPABASE_URL, c.env.SUPABASE_SERVICE_ROLE_KEY);

    try {
        const { data: existingUsers } = await supabaseAdmin.auth.admin.listUsers({ perPage: 1000 });
        const usernameTaken = existingUsers?.users?.some((u: any) => u.user_metadata?.username?.toLowerCase() === username.toLowerCase());
        if (usernameTaken) return c.json({ error: 'Username is already taken' }, 400);
    } catch (e: any) { /* continue */ }

    const { data, error } = await supabaseAdmin.auth.admin.createUser({
        email, password, email_confirm: false,
        user_metadata: { 
            full_name: name.trim(), display_name: name.trim(), dob, mobile: mobile.trim(), 
            address: address?.trim() || '', school: school?.trim() || '', 
            username: username.trim().toLowerCase(), avatar_url: avatar || '' 
        }
    });

    if (error) return c.json({ error: error.message }, 400);

    try { await supabaseAdmin.auth.signInWithOtp({ email }); } catch (e: any) { /* non-critical */ }

    return c.json({ success: true, user_id: data.user?.id });
});

app.post('/api/signup/check-username', async (c) => {
    const { username } = await c.req.json();
    if (!username || typeof username !== 'string' || username.trim().length < 3) return c.json({ available: false, error: 'Username too short' });
    if (!/^[a-zA-Z0-9_]+$/.test(username)) return c.json({ available: false, error: 'Invalid characters' });

    const supabaseAdmin = createClient(c.env.SUPABASE_URL, c.env.SUPABASE_SERVICE_ROLE_KEY);

    try {
        const { data: existingUsers } = await supabaseAdmin.auth.admin.listUsers({ perPage: 1000 });
        const taken = existingUsers?.users?.some((u: any) => u.user_metadata?.username?.toLowerCase() === username.toLowerCase());
        return c.json({ available: !taken });
    } catch (e: any) { 
        return c.json({ available: true }); 
    }
});

app.post('/api/signup/verify-email', async (c) => {
    if (!c.env.SUPABASE_URL) return c.json({ error: 'Supabase URL missing' }, 500);
    const { email, token } = await c.req.json();
    if (!email || !token || token.length !== 6) return c.json({ error: 'Invalid verification code' }, 400);

    const supabaseAdmin = createClient(c.env.SUPABASE_URL, c.env.SUPABASE_SERVICE_ROLE_KEY);
    const { data, error } = await supabaseAdmin.auth.verifyOtp({ email, token, type: 'email' });

    if (error) return c.json({ error: error.message }, 400);
    return c.json({ success: true });
});

app.get('/login', async (c) => {
